#!/usr/bin/env bash
set -Eeuo pipefail
begin_deployment() { DEPLOYMENT_ID="$(timestamp)-$(git -C "$PROJECT_ROOT" rev-parse --short=7 HEAD)"; GIT_COMMIT=$(git -C "$PROJECT_ROOT" rev-parse HEAD); GIT_BRANCH=$(git -C "$PROJECT_ROOT" branch --show-current); DEPLOY_RUNTIME="$PROJECT_ROOT/runtime/deployment/$DEPLOYMENT_ID"; mkdir -p "$DEPLOY_RUNTIME"; STARTED_AT=$(date -u '+%Y-%m-%dT%H:%M:%SZ'); info "deployment=$DEPLOYMENT_ID mode=$1"; write_report running; }
write_report() { local status=$1; [ -n "${DEPLOY_RUNTIME:-}" ] || return; { printf '{\n  "deployment_id": "%s",\n  "mode": "%s",\n  "status": "%s",\n  "commit": "%s",\n  "branch": "%s",\n  "production_url": "%s",\n  "backup_path": "%s"\n}\n' "$(json_escape "$DEPLOYMENT_ID")" "$(json_escape "$COMMAND")" "$status" "$(json_escape "$GIT_COMMIT")" "$(json_escape "$GIT_BRANCH")" "$(json_escape "$PRODUCTION_URL")" "$(json_escape "$REMOTE_BACKUP_ROOT/$DEPLOYMENT_ID")"; } > "$DEPLOY_RUNTIME/deployment.json"; { printf '# Production deployment %s\n\n- Mode: %s\n- Status: %s\n- Commit: %s\n- Production: %s\n- Backup: %s\n- Rollback: `./scripts/deploy-production rollback %s`\n' "$DEPLOYMENT_ID" "$COMMAND" "$status" "$GIT_COMMIT" "$PRODUCTION_URL" "$REMOTE_BACKUP_ROOT/$DEPLOYMENT_ID" "$DEPLOYMENT_ID"; } > "$DEPLOY_RUNTIME/deployment.md"; }
finish_deployment() { write_report "$1"; ok "deployment $DEPLOYMENT_ID completed"; }
